glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv;
out vec4 tint;
vec4 vert () {
  vec4 p=vec4(a_position,1.0);
  #if USE_LOCAL
    p=cc_matWorld*p;
  #endif
  uv=a_texCoord;tint=a_color;
  return cc_matViewProj*p;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
uniform sampler2D cc_spriteTexture;
layout(std140) uniform Inlay { vec4 exposure; };
in vec2 uv;
in vec4 tint;
vec4 frag () {
  float t=exposure.x;
  float dragon=step(1.5,exposure.y)-step(2.5,exposure.y);
  float right=smoothstep(.42,.58,uv.x);
  float unfold=1.0-smoothstep(.02,.82,t);
  vec2 st=uv;
  st.x+=(right*2.0-1.0)*.066*unfold;
  st.y-=mix(.033,-.026,right)*unfold;
  st=mix(st,(st-vec2(.001,.095))/.70,dragon*(1.0-right));
  st.y+=.0035*sin(st.x*9.0+t*2.5)*exp(-t*1.1);
  if(min(st.x,st.y)<0.0 || max(st.x,st.y)>1.0)return vec4(0.0);
  vec4 print=CCSampleWithAlphaSeparated(cc_spriteTexture,clamp(st,0.0,1.0));
  if(dragon<.5){
    float radius=length(st-.5);
    print.a*=smoothstep(.351,.395,radius)*(1.0-smoothstep(.18,.38,abs(st.y-.5)))*.74;
    print.rgb=mix(print.rgb,vec3(dot(print.rgb,vec3(.26,.62,.12))),.28);
  }
  if(print.a<.012)return vec4(0.0);
  float value=dot(print.rgb,vec3(.26,.62,.12));
  if(dragon>.5) print.rgb=mix(vec3(.11,.075,.048),vec3(.9,.66,.40),value);
  float dist=mix(.37*st.x+.63*(1.0-st.y),.61*st.x+.39*st.y,dragon);
  float boundary=dist+.047*sin(14.0*st.y+6.0*st.x)+.052*(1.0-value);
  float mask=smoothstep(-.15,.09,(t-.035)*1.78-boundary);
  mask=max(mask,.16*smoothstep(.015,.16,t)*smoothstep(.42,.82,value));
  float front=boundary-(t-.09)*1.30;
  float glint=exp(-front*front*141.0);
  float second=boundary-.27-(t-.89)*.93;
  float grazing=exp(-second*second*108.0)*smoothstep(.73,1.06,t);
  vec3 metal=mix(vec3(.74,.85,1.0),vec3(1.0,.82,.48),max(dragon,step(4.5,exposure.y)));
  float relief=smoothstep(.23,.85,value);
  vec3 rgb=print.rgb*(.62+.22*relief+.12*glint)
           +metal*(glint*.46+grazing*.25)*relief;
  vec2 edge=min(uv,1.0-uv);
  float soft=smoothstep(0.0,.049,edge.x)*smoothstep(0.0,.055,edge.y);
  float alpha=print.a*mask*exposure.z*tint.a*soft*(.66+.23*relief);
  return vec4(rgb*alpha,alpha);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

